#!/usr/bin/env python3
"""Vellum House V5 static-site builder — bilingual pages, HTML metadata and sitemap.
Runs with Python stdlib only. The backend is Google Apps Script, deployed separately.
"""
from pathlib import Path
from html import escape as e
import json
R=Path(__file__).resolve().parents[1]
BASE='https://vhouse.ir/'
CAL='https://cal.com/vhouse/30min?overlayCalendar=true&layout=month_view'
LANGS=['en','fa']
NAV={
'en':[('services','Services'),('approach','Our approach'),('pathways','For students'),('about','About us')],
'fa':[('services','خدمات'),('approach','روش کار ما'),('pathways','مسیرهای تحصیلی'),('about','درباره ما')]
}
PAGES={
'en':{'home':('Personalised Academic Management | Vellum House','Vellum House discovers each student’s strengths and goals, then coordinates classes, mentoring, competitions and university planning into one personalised educational journey.'),'services':('Our Services | Vellum House','Personalised academic management, specialist classes, progress mentoring, international competitions, talent development and admissions strategy. Choose complete support or individual services.'),'approach':('Our Approach | Vellum House','From Point A to Point B: understand the student, define their goals, design a custom strategy, coordinate the work and continuously review progress.'),'pathways':('Who We Help | Vellum House','Tailored education planning and expert academic support for children, secondary-school students, university applicants and postgraduate students.'),'about':('Our Founders & Team | Vellum House','Meet the people and educational philosophy behind Vellum House, a private academic management service built around individual potential.'),'contact':('Free Initial Consultation | Vellum House','Tell Vellum House about your academic goals. Submit a short enquiry and immediately choose a free 30-minute consultation on Cal.com.'),'journal':('Resources | Vellum House','Resources and practical guidance on personalised learning, examinations, talent development and university planning.'),'privacy':('Privacy Notice | Vellum House','Understand how Vellum House collects, stores and uses enquiries from students and families, including the Google Sheets and Gmail systems.'),'terms':('Terms of Service | Vellum House','Read the scope, expectations and limitations of free consultations, personalised education services and university strategy.')},
'fa':{'home':('مدیریت اختصاصی مسیر تحصیلی | ولوم هاوس','ولوم هاوس با شناخت توانمندی‌ها و هدف‌های هر دانش‌آموز، آموزش، منتورینگ، فعالیت‌های علمی و برنامه‌ریزی دانشگاهی را در یک مسیر اختصاصی هماهنگ می‌کند.'),'services':('خدمات آموزشی و مشاوره | ولوم هاوس','مدیریت کامل مسیر تحصیلی، کلاس تخصصی، منتورینگ، پرورش استعداد، مسابقات بین‌المللی و برنامه‌ریزی پذیرش دانشگاه؛ یک خدمت یا برنامه‌ای جامع.'),'approach':('روش کار ما | ولوم هاوس','از شناخت جایگاه امروز تا رسیدن به هدف مناسب؛ با ارزیابی توانمندی‌ها، طراحی مسیر اختصاصی، هماهنگی اجرا و سنجش مداوم پیشرفت.'),'pathways':('برای چه دانش‌آموزانی؟ | ولوم هاوس','برنامه‌ریزی و پشتیبانی تحصیلی متناسب با دانش‌آموزان دبستان و دبیرستان، متقاضیان دانشگاه و دانشجویان تحصیلات تکمیلی.'),'about':('بنیان‌گذاران و تیم | ولوم هاوس','آشنایی با بنیان‌گذاران و رویکرد ولوم هاوس؛ مجموعه‌ای برای راهبری اختصاصی مسیر تحصیلی هر دانش‌آموز.'),'contact':('جلسه آشنایی رایگان | ولوم هاوس','فرم کوتاه آشنایی را تکمیل کنید و بلافاصله زمان جلسه آنلاین رایگان ۳۰ دقیقه‌ای را انتخاب کنید.'),'journal':('راهنماها و منابع | ولوم هاوس','مطالب کاربردی درباره برنامه‌ریزی تحصیلی، آزمون‌ها، شناخت استعداد، پروژه‌ها و مسیر ورود به دانشگاه.'),'privacy':('حریم خصوصی | ولوم هاوس','با نحوه دریافت و نگهداری اطلاعات خانواده‌ها در فرم آشنایی، گوگل شیت و ایمیل ولوم هاوس آشنا شوید.'),'terms':('شرایط همکاری | ولوم هاوس','محدوده خدمات، شرایط جلسه آشنایی رایگان و چارچوب همکاری اختصاصی با خانواده‌ها را بخوانید.')}
}
def fn(key,lang):
 if key=='home':return 'index.html' if lang=='fa' else 'en.html'
 return key+('-fa' if lang=='fa' else '')+'.html'
def a(key,txt,lang,cls='',attr=''):
 return f'<a class="{cls}" href="{fn(key,lang)}" {attr}>{e(txt)}</a>'
def cta(lang,cls='btn btn-gold'):
 return a('contact','درخواست جلسه آشنایی رایگان' if lang=='fa' else 'Book a free discovery call',lang,cls)
def media(label,extra=''):
 return f'<div class="media-slot {extra}" role="img" aria-label="Reserved space: {e(label)}"><span class="slot-hairline"></span><span class="slot-label">{e(label)}</span><span class="slot-cross">+</span></div>'
def head(key,lang):
 title,desc=PAGES[lang][key]; path=fn(key,lang); other='en' if lang=='fa' else 'fa'
 alternate=fn(key,other)
 # English default /en.html, Persian canonical / at index.html, /fa.html preserved as alias.
 url=BASE if key=='home' and lang=='fa' else BASE+path
 org={"@context":"https://schema.org","@type":"EducationalOrganization","name":"Vellum House","url":BASE,"email":"vellumhouse.edu@gmail.com","description":desc,"availableLanguage":["Persian","English"]}
 return f'''<!doctype html><html lang="{lang}" dir="{'rtl' if lang=='fa' else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1722"><meta name="description" content="{e(desc)}"><title>{e(title)}</title><link rel="canonical" href="{url}"><link rel="alternate" hreflang="en" href="{BASE+fn(key,'en')}"><link rel="alternate" hreflang="fa" href="{BASE if key=='home' else BASE+fn(key,'fa')}"><link rel="alternate" hreflang="x-default" href="{BASE}"><meta property="og:type" content="website"><meta property="og:site_name" content="Vellum House"><meta property="og:locale" content="{'fa_IR' if lang=='fa' else 'en_US'}"><meta property="og:url" content="{url}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="assets/style.css" as="style"><link rel="stylesheet" href="assets/style.css"><script defer src="assets/config.js"></script><script defer src="assets/main.js"></script><script type="application/ld+json">{json.dumps(org,ensure_ascii=False).replace('</','<\\/')}</script></head>'''
def header(key,lang):
 links=''.join(a(k,t,lang,'active' if k==key else '') for k,t in NAV[lang]); other='fa' if lang=='en' else 'en'
 language=f'<a class="lang-switch" href="{fn(key,other)}" lang="{other}" hreflang="{other}" aria-label="{ "Change to Persian" if lang=="en" else "Switch to English" }">{ "فارسی" if lang=="en" else "EN" }</a>'
 return f'''<body class="{'is-rtl' if lang=='fa' else 'is-ltr'}"><a class="skip-link" href="#main">{'رفتن به محتوا' if lang=='fa' else 'Skip to content'}</a><header class="site-header"><div class="container nav-inner"><a class="brand" href="{fn('home',lang)}" aria-label="Vellum House"><span class="brand-mark">V<span>H</span></span><span class="brand-name">VELLUM HOUSE<small>{'مدیریت اختصاصی مسیر تحصیلی' if lang=='fa' else 'PRIVATE ACADEMIC MANAGEMENT'}</small></span></a><button class="nav-toggle" id="menu" type="button" aria-label="{'باز کردن فهرست' if lang=='fa' else 'Open navigation'}" aria-expanded="false" aria-controls="navigation"><i></i><i></i><i></i></button><nav id="navigation" class="primary-nav" aria-label="{'فهرست اصلی' if lang=='fa' else 'Main navigation'}">{links}{language}{cta(lang,'btn btn-nav')}</nav></div></header>'''
def footer(lang):
 fa=lang=='fa'
 motto='هر استعداد، مسیری مخصوص به خود دارد.' if fa else 'Exceptional futures are personal.'
 short='از شناخت توانمندی‌ها تا ساختن مسیر؛ آموزش، منتورینگ و راهبری تحصیلی در کنار یکدیگر.' if fa else 'From understanding potential to building the plan: teaching, mentorship and academic direction, connected.'
 return f'''<footer class="site-footer"><div class="container footer-grid"><div><p class="footer-wordmark">VELLUM HOUSE</p><h2>{motto}</h2><p>{short}</p></div><div><h3>{'آشنایی' if fa else 'Explore'}</h3>{a('services','خدمات' if fa else 'Services',lang)}{a('approach','روش کار' if fa else 'Our approach',lang)}{a('about','تیم ما' if fa else 'Our team',lang)}{a('journal','منابع' if fa else 'Resources',lang)}</div><div><h3>{'ارتباط' if fa else 'Contact'}</h3>{a('contact','جلسه آشنایی رایگان' if fa else 'Free discovery call',lang)}<a href="mailto:vellumhouse.edu@gmail.com" dir="ltr">vellumhouse.edu@gmail.com</a>{a('privacy','حریم خصوصی' if fa else 'Privacy',lang)}{a('terms','شرایط همکاری' if fa else 'Terms',lang)}</div></div><div class="container footer-base"><span>© 2026 Vellum House</span><span>{'با دقت برای هر مسیر' if fa else 'Thoughtfully built around each student.'}</span></div></footer><button id="back-to-top" type="button" aria-label="{'بازگشت به بالا' if fa else 'Back to top'}" title="{'بازگشت به بالا' if fa else 'Back to top'}">↑</button></body></html>'''
def wrap(key,lang,content):return head(key,lang)+header(key,lang)+f'<main id="main">{content}</main>'+footer(lang)
def eyebrows(en,fa,lang):return f'<p class="eyebrow">{fa if lang=="fa" else en}</p>'
def closing(lang):
 if lang=='fa':
  title='از همین‌جا شروع کنیم؟';description='هر مسیر خوبی با شناخت درست آغاز می‌شود. فرم کوتاه را تکمیل کنید و زمان جلسه آشنایی رایگان را انتخاب کنید.'
 else:
  title='Let’s find your next step.';description='Every meaningful plan begins with understanding the student. Tell us a little about your goals, then choose your free introductory meeting.'
 return f'<section class="closing-band"><div class="container closing-inner">{eyebrows("THE NEXT STEP","گام بعدی",lang)}<h2>{title}</h2><p>{description}</p>{cta(lang)}</div></section>'
def home(lang):
 fa=lang=='fa'
 if fa:
  hero_title='اول شما را می‌شناسیم.<br><em>بعد مسیرتان را می‌سازیم.</em>'
  intro='در ولوم هاوس، از شناخت استعدادها، توانمندی‌ها و علایق هر دانش‌آموز شروع می‌کنیم و هدف‌هایی متناسب با ظرفیت واقعی او انتخاب می‌کنیم. سپس آموزش، منتورینگ، فرصت‌های علمی و برنامه‌ریزی تحصیلی لازم را در مسیری اختصاصی طراحی و مدیریت می‌کنیم.'
  small='نه یک برنامه آماده برای همه؛ مسیری که مخصوص شما طراحی شده است.'
 else:
  hero_title='Know your starting point.<br><em>Build what comes next.</em>'
  intro='At Vellum House, we start by understanding each student’s strengths, interests and opportunities, then define goals that bring out their potential. We design and manage the teaching, mentoring, experiences and academic strategy needed to move from where they are to where they want to be.'
  small='Not another standard programme. A plan built around the individual.'
 h=f'''<section class="hero"><div class="container hero-grid"><div class="hero-copy">{eyebrows('A DIFFERENT APPROACH TO EDUCATION','نگاهی متفاوت به مسیر تحصیلی',lang)}<h1>{hero_title}</h1><p class="hero-intro">{intro}</p><p class="hero-aside">{small}</p><div class="button-row">{cta(lang)}{a('approach','روش کار ما را ببینید' if fa else 'Explore our approach',lang,'text-cta')}</div><div class="hero-caption"><span class="gold-dot"></span>{'جلسه آشنایی اولیه، رایگان و آنلاین است.' if fa else 'Your first 30-minute online conversation is free.'}</div></div><div class="hero-visual"><div class="hero-topline"><span>VELLUM / METHOD</span><span>01 — 04</span></div><div class="journey-graphic"><div class="graph-node start"><span class="graph-caption">{'نقطه A · امروز' if fa else 'POINT A · TODAY'}</span><strong>{'شناخت' if fa else 'Understand'}</strong><small>{'توانمندی‌ها · علایق · فرصت‌ها' if fa else 'Strengths · interests · opportunities'}</small></div><div class="graph-path" aria-hidden="true"><span></span><span></span><span></span><i>→</i></div><div class="graph-node finish"><span class="graph-caption">{'نقطه B · فردا' if fa else 'POINT B · NEXT'}</span><strong>{'شکوفایی' if fa else 'Potential'}</strong><small>{'هدف‌های معنادار · رشد واقعی' if fa else 'Meaningful goals · real progress'}</small></div></div><p class="visual-caption">{'فاصله میان این دو نقطه را با برنامه‌ای شخصی و همراهی واقعی طی می‌کنیم.' if fa else 'Everything in between: one intentional, evolving plan.'}</p><div class="visual-index"><span>01 / DISCOVER</span><span>02 / DESIGN</span><span>03 / DELIVER</span><span>04 / EVOLVE</span></div></div></div><div class="container hero-scroll"><span>{'برای دیدن ادامه، پایین بروید' if fa else 'SCROLL TO EXPLORE'}</span><span>↓</span></div></section>'''
 problem=('کلاس‌های بیشتر، همیشه به معنی پیشرفت بیشتر نیست.','گاهی کلاس‌ها، آزمون‌ها، پروژه‌ها و تصمیم‌های دانشگاهی جدا از هم پیش می‌روند. نتیجه، فشار بیشتر و مسیری نامشخص است. ما همه این بخش‌ها را با یک هدف مشترک هماهنگ می‌کنیم.','آموزش','منتورینگ','مسیر دانشگاه','برنامه‌ای هماهنگ برای یک دانش‌آموز') if fa else ('More classes do not always mean more progress.','Tutors, exams, projects and university decisions often happen independently. We bring them together, so every step serves a meaningful purpose.','Teaching','Mentorship','University direction','One connected plan for one student')
 h+=f'''<section class="section problem-section"><div class="container split-layout"><div>{eyebrows('WHY VELLUM HOUSE','چرا ولوم هاوس؟',lang)}<h2>{problem[0]}</h2><p class="section-lead">{problem[1]}</p>{a('services','خدمات ما' if fa else 'See how we help',lang,'text-cta dark')}</div><div class="connected-board"><div class="board-pill">{problem[2]}</div><div class="board-pill">{problem[3]}</div><div class="board-pill">{problem[4]}</div><div class="board-focus"><span>VELLUM HOUSE</span><strong>{problem[5]}</strong></div></div></div></section>'''
 steps=([('01','شناخت نقطه شروع','استعدادها، مهارت‌ها، علایق، نیازها و فرصت‌های پیش روی دانش‌آموز را بررسی می‌کنیم.'),('02','انتخاب مقصد درست','هدف‌هایی متناسب با ویژگی‌ها و آرزوهای او مشخص می‌کنیم؛ نه هدف‌هایی یکسان برای همه.'),('03','طراحی و مدیریت مسیر','کلاس، منتورینگ، پروژه، مسابقه و برنامه‌ریزی دانشگاهی را متناسب با نیاز کنار هم می‌چینیم.'),('04','سنجش و اصلاح','پیشرفت را دنبال می‌کنیم و با تغییر شرایط یا هدف‌ها، برنامه را به‌روز می‌کنیم.')] if fa else [('01','Discover your Point A','Understand strengths, skills, interests, current challenges and the opportunities ahead.'),('02','Define the right Point B','Set ambitious but individual goals based on potential, priorities and real circumstances.'),('03','Build and manage the journey','Coordinate specialist classes, mentoring, projects, competitions and admissions planning.'),('04','Review and adapt','Track progress, share clear updates and adjust the plan as the student evolves.')])
 h+=f'''<section class="section method-section" id="method"><div class="container">{eyebrows('THE VELLUM METHOD','روش کار ولوم هاوس',lang)}<div class="section-heading-row"><h2>{'از نقطه A تا نقطه B، هیچ قدمی اتفاقی نیست.' if fa else 'From Point A to Point B, with purpose.'}</h2><p>{'مسیر از یک شناخت واقعی آغاز می‌شود و با پیگیری مداوم زنده می‌ماند.' if fa else 'A thoughtful process, tailored to the student and reviewed as life changes.'}</p></div><div class="method-grid">'''+''.join(f'<article class="method-step"><span>{n}</span><h3>{title}</h3><p>{body}</p></article>' for n,title,body in steps)+'</div></div></section>'
 serv=([('مدیریت اختصاصی مسیر تحصیلی','برنامه‌ریزی، هماهنگی تیم آموزشی و پیگیری همه‌جانبه، زیر نظر یک مجموعه.'),('کلاس‌های تخصصی','آموزش متناسب با نیاز درسی، سطح علمی، آزمون‌ها و سبک یادگیری.'),('منتورینگ و گزارش پیشرفت','هدف‌گذاری، بررسی پیشرفت و تصمیم‌گیری آگاهانه در هر مرحله.'),('پرورش استعداد و رزومه','پروژه‌های علمی، تجربه‌های عملی و توسعه توانمندی‌های فردی.'),('مسابقات و فرصت‌های بین‌المللی','انتخاب و آمادگی برای رقابت‌ها و فرصت‌های مرتبط با استعداد دانش‌آموز.'),('راهبرد پذیرش دانشگاه','انتخاب دانشگاه، شناخت الزامات، برنامه‌ریزی آزمون‌ها و آماده‌سازی مسیر اقدام.')] if fa else [('Full academic management','One coordinated education plan, teaching team and ongoing oversight.'),('Expert-led classes','Specialist lessons aligned with learning needs, curricula and examinations.'),('Mentorship & progress tracking','Clear priorities, regular check-ins and progress updates you can use.'),('Talent & profile development','Purposeful projects, skill building and meaningful portfolio experiences.'),('International opportunities','Relevant competitions, academic programmes and challenge-based experiences.'),('University admissions strategy','Best-fit university research, application planning and preparation milestones.')])
 h+=f'''<section class="section services-section" id="services"><div class="container">{eyebrows('ONE TEAM. MANY POSSIBILITIES.','یک تیم، خدمات متناسب با هر مسیر',lang)}<div class="section-heading-row"><h2>{'همه خدمات در یک مسیر؛ یا فقط همان بخشی که نیاز دارید.' if fa else 'Complete support, or just what you need.'}</h2><p>{'میزان و نوع همکاری برای هر دانش‌آموز متفاوت است. شما می‌توانید برنامه‌ای جامع یا یک خدمت مشخص انتخاب کنید.' if fa else 'Choose comprehensive academic management or individual services. Every scope is agreed around your goals.'}</p></div><div class="service-grid">'''+''.join(f'<article class="service-tile"><span class="tile-num">0{i}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(serv,1))+f'</div><div class="section-link">{a("services","آشنایی با تمام خدمات" if fa else "Explore every service",lang,"text-cta dark")}</div></div></section>'
 h+=f'''<section class="section proof-section"><div class="container">{eyebrows('THE WORK, MADE VISIBLE','ارزش همراهی، به شکل ملموس',lang)}<div class="section-heading-row"><h2>{'پیشرفت را قابل پیگیری می‌کنیم.' if fa else 'Not just a plan. Visible follow-through.'}</h2><p>{'نمونه‌های واقعی پس از دریافت رضایت خانواده‌ها اضافه می‌شوند. ساختار زیر صرفاً نمایشی است.' if fa else 'Real examples will be added with consent. The structure below is illustrative, not a client result.'}</p></div><div class="proof-grid"><div class="preview-report"><p class="eyebrow">{'نمونه نمایشی · گزارش پیشرفت' if fa else 'ILLUSTRATIVE · PROGRESS UPDATE'}</p><h3>{'گزارش یک مسیر منسجم' if fa else 'A clear view of the journey'}</h3><div class="report-row"><span>{'هدف‌های این دوره' if fa else 'Current priorities'}</span><i></i></div><div class="report-row"><span>{'فعالیت‌ها و کلاس‌ها' if fa else 'Learning & activities'}</span><i></i></div><div class="report-row"><span>{'نقاط قوت و چالش‌ها' if fa else 'Strengths & challenges'}</span><i></i></div><div class="report-row"><span>{'اقدام‌های بعدی' if fa else 'Next actions'}</span><i></i></div><p class="micro">{'این یک نمونه از قالب گزارش است؛ داده‌ای از دانش‌آموز واقعی نمایش داده نشده.' if fa else 'Sample report layout only. No real student data is shown.'}</p></div>{media('FOUNDER / INTRO VIDEO','video-slot')}</div></div></section>'''
 h+=f'''<section class="section audience-section"><div class="container">{eyebrows('WHO WE WORK WITH','مخاطبان ما',lang)}<div class="section-heading-row"><h2>{'هر سنی، نقطه شروع خودش را دارد.' if fa else 'A thoughtful next step, at every stage.'}</h2><p>{'از ساختن پایه‌های یادگیری تا آماده شدن برای دانشگاه و پژوهش.' if fa else 'From building foundations to university strategy and the years beyond.'}</p></div><div class="audience-grid">'''+''.join(f'<a href="{fn("pathways",lang)}" class="audience-card"><span>{tag}</span><h3>{ttl}</h3><p>{ds}</p><b aria-hidden="true">↗</b></a>' for tag,ttl,ds in (([('01 / 8–12','سال‌های پایه','شناخت استعداد و ساختن عادت‌های یادگیری'),('02 / 13–18','دبیرستان و آزمون‌ها','IGCSE، A Level، IB، مسابقات و تصمیم‌های دانشگاهی'),('03 / 18+','دانشگاه و فراتر','انتخاب رشته، درخواست پذیرش و آماده‌سازی پژوهشی')] if fa else [('01 / 8–12','Growing foundations','Confidence, curiosity and strong learning habits'),('02 / 13–18','Secondary & sixth form','School programmes, exams, competitions and admissions'),('03 / 18+','University & beyond','Applications, academic direction and research readiness')])))+f'</div></div></section>'
 h+=f'''<section class="section story-section"><div class="container">{eyebrows('REAL PEOPLE. REAL JOURNEYS.','تجربه‌های واقعی، روایت‌های قابل اعتماد',lang)}<div class="section-heading-row"><h2>{'اعتماد با تجربه‌های واقعی ساخته می‌شود.' if fa else 'Let the work speak for itself.'}</h2><p>{'جای روایت‌ها و تجربه‌های خانواده‌ها را از حالا در نظر گرفته‌ایم؛ تنها با اجازه آن‌ها منتشر می‌کنیم.' if fa else 'Space reserved for permissioned student stories, documented outcomes and family testimonials.'}</p></div><div class="testimonial-grid">{media('CLIENT STORY / VIDEO')}{media('DOCUMENTED CASE STUDY')}{media('FAMILY TESTIMONIAL')}</div></div></section>'''
 h+=f'''<section class="section team-preview"><div class="container split-layout"><div>{eyebrows('THE PEOPLE BEHIND THE PLAN','آدم‌های پشت هر برنامه',lang)}<h2>{'تجربه، مسئولیت‌پذیری و نگاه شخصی.' if fa else 'Guidance led by people, not templates.'}</h2><p class="section-lead">{'ولوم هاوس با همراهی متخصصان آموزشی و بنیان‌گذارانی شکل گرفته که به شناخت دقیق و تصمیم‌گیری سنجیده باور دارند.' if fa else 'Vellum House brings together education-led direction and a growing network of specialists, selected for the student’s needs.'}</p>{a('about','درباره تیم و بنیان‌گذاران' if fa else 'Meet the founders',lang,'text-cta dark')}</div><div class="founder-pair">{media('FOUNDER / PORTRAIT')}{media('CO-FOUNDER / PORTRAIT')}</div></div></section>'''
 h+=closing(lang)
 return h

def service_page(lang):
 fa=lang=='fa'
 title='خدماتی که دورِ نیاز شما شکل می‌گیرند.' if fa else 'The support you need. Nothing off the shelf.'
 intro='ابتدا نقطه شروع و هدف‌های دانش‌آموز را می‌شناسیم. سپس متناسب با آن، خدمات لازم را به‌صورت یک برنامه کامل یا چند خدمت مستقل پیشنهاد می‌کنیم.' if fa else 'We identify your current position and goals first. Then we recommend a connected programme—or individual services—depending on what will actually help.'
 cards=([('مدیریت اختصاصی تحصیل','طراحی یک نقشه راه شخصی، هماهنگی معلمان و متخصصان، زمان‌بندی، نظارت بر اجرا و اصلاح برنامه.'),('آموزش و آمادگی آزمون','کلاس‌های اختصاصی و گروهی متناسب با سطح درسی؛ پشتیبانی از IGCSE، A Level، IB و آزمون‌های مناسب مسیر.'),('منتورینگ و گزارش پیشرفت','جلسه‌های منظم برای پیگیری اهداف، مرور دستاوردها، تشخیص موانع و گزارش روشن به خانواده.'),('شناخت و پرورش استعداد','ارزیابی اولیه علایق و مهارت‌ها، کمک به ساخت پروژه، پژوهش و تجربه‌های مرتبط با توانمندی فردی.'),('مسابقات و فعالیت‌های بین‌المللی','پیشنهاد رقابت‌ها و برنامه‌های متناسب با سن و علاقه؛ مانند المپیادهای علمی، IYPT و برنامه‌های پژوهشی معتبر، در صورت تناسب و امکان شرکت.'),('برنامه‌ریزی پذیرش دانشگاه','انتخاب دانشگاه بر اساس تناسب علمی و شخصی، شناخت شرایط پذیرش، زمان‌بندی آزمون‌ها و هدایت رزومه و درخواست‌ها.'),('پشتیبانی دانشجویان و متقاضیان تحصیلات تکمیلی','جهت‌دهی علمی، برنامه پژوهشی، یافتن فرصت‌های مناسب و آماده‌سازی درخواست‌های دانشگاهی.')]
 if fa else [('Private academic management','A personal roadmap, coordinated educators, activity planning, progress monitoring and adjustments over time.'),('Specialist teaching & examinations','Individual and group lessons appropriate to level and curriculum, including IGCSE, A Level, IB and relevant assessments.'),('Mentoring & progress reporting','Regular goal reviews, clear family updates, identification of challenges and coordinated next steps.'),('Talent discovery & development','Interest and skills mapping, meaningful projects, research exposure and portfolio support.'),('Competitions & international experiences','Guidance toward relevant academic competitions and experiences, such as IYPT and suitable research programmes, where eligible.'),('University admissions strategy','Best-fit university selection, requirements, application timelines, tests, portfolio and submission preparation.'),('University & postgraduate support','Academic direction, research readiness, opportunities and carefully planned applications.')])
 blocks=''.join(f'<article class="detail-card"><span>0{i}</span><div><h2>{t}</h2><p>{d}</p></div></article>' for i,(t,d) in enumerate(cards,1))
 p=interior_hero(lang,'SERVICES','خدمات',title,intro)
 p+=f'''<section class="section light-section"><div class="container">{eyebrows('TAILORED IN SCOPE','مقیاس همکاری، متناسب با شما',lang)}<div class="detail-list">{blocks}</div></div></section>'''
 p+=f'''<section class="section twin-callout"><div class="container compare-grid"><div><span class="overline">{'برنامه جامع' if fa else 'COMPLETE MANAGEMENT'}</span><h2>{'یک تیم برای کل مسیر' if fa else 'One team across the journey'}</h2><p>{'برنامه‌ریزی، انتخاب متخصص، هماهنگی کلاس‌ها، فعالیت‌های جانبی و پیگیری پیشرفت در یک چارچوب منسجم.' if fa else 'Planning, specialist selection, teaching, experiences and progress oversight within one coordinated relationship.'}</p></div><div><span class="overline">{'خدمات مستقل' if fa else 'INDIVIDUAL SUPPORT'}</span><h2>{'فقط همان بخش لازم' if fa else 'Help with one specific need'}</h2><p>{'ممکن است فقط به کلاس، یک دوره منتورینگ، ارزیابی یا برنامه‌ریزی پذیرش نیاز داشته باشید؛ انتخاب با شماست.' if fa else 'Choose a class, an assessment, mentoring, a project or university application strategy without a full programme.'}</p></div></div><div class="container pricing-note">{'هزینه‌ها پس از شناخت نیاز و توافق بر محدوده خدمات به‌صورت اختصاصی اعلام می‌شوند.' if fa else 'Fees are quoted individually after we understand your needs and agree the scope.'}</div></section>'''
 return p+closing(lang)

def approach_page(lang):
 fa=lang=='fa'
 title='اول شناخت، بعد تصمیم؛ همیشه همراه با بازبینی.' if fa else 'A better plan begins with understanding.'
 intro='قرار نیست دانش‌آموز خود را با یک قالب آماده تطبیق دهد. ما مسیر را بر اساس توانمندی‌ها، فرصت‌ها، هدف‌ها و تغییرات واقعی زندگی او طراحی می‌کنیم.' if fa else 'The student should not have to fit a ready-made system. We build an evolving plan around their strengths, opportunities, ambitions and real circumstances.'
 data=([('01','نقطه A: جایگاه امروز','با گفت‌وگو، بررسی سوابق و در صورت نیاز ارزیابی‌های تخصصی، علایق، مهارت‌ها و چالش‌ها را شناسایی می‌کنیم.'),('02','نقطه B: مقصد مناسب','هدف‌های تحصیلی و فردی را با توجه به ظرفیت، علایق، شرایط و فرصت‌های واقعی انتخاب می‌کنیم.'),('03','نقشه راه شخصی','نیازهای آموزشی، پروژه‌ها، فعالیت‌های تکمیلی، برنامه آزمون و مسیر دانشگاه را اولویت‌بندی می‌کنیم.'),('04','اجرای هماهنگ','از انتخاب متخصص تا هماهنگی برنامه، ارتباط با خانواده و اجرای اقدامات توافق‌شده کنار دانش‌آموز هستیم.'),('05','سنجش و انعطاف','در بازه‌های توافق‌شده پیشرفت را مرور می‌کنیم و در صورت لزوم مسیر را تغییر می‌دهیم.')]
 if fa else [('01','Point A: Understand today','Through conversations, background review and assessments when suitable, we map strengths, interests, skills and current barriers.'),('02','Point B: Choose meaningful goals','Set educational and personal goals based on interests, capabilities, real-world options and the student’s priorities.'),('03','Design a personal roadmap','Prioritise learning, projects, experiences, examinations and university planning according to their relevance.'),('04','Coordinate execution','Bring together appropriate teaching, mentoring, scheduling, family communication and agreed deliverables.'),('05','Review and evolve','Monitor progress at agreed intervals; adjust the roadmap when the student’s needs or circumstances change.')])
 p=interior_hero(lang,'OUR METHOD','روش کار',title,intro)
 p+=f'<section class="section"><div class="container"><div class="method-list">'+''.join(f'<article class="method-list-row"><span>{n}</span><div><h2>{t}</h2><p>{d}</p></div></article>' for n,t,d in data)+'</div></div></section>'
 p+=f'''<section class="section report-section"><div class="container split-layout"><div>{eyebrows('WHAT FAMILIES RECEIVE','خانواده چه چیزی دریافت می‌کند؟',lang)}<h2>{'شفافیت در مسیر و مسئولیت‌ها.' if fa else 'Clarity, not just activity.'}</h2><p>{'پیش از شروع همکاری، محدوده خدمات، مسئولیت‌ها، زمان‌بندی، هزینه و شیوه گزارش‌دهی توافق می‌شود. نتیجه دانشگاهی یا نمره مشخص را تضمین نمی‌کنیم؛ چیزی که مدیریت می‌کنیم کیفیت برنامه‌ریزی و پیگیری اجرای خدمات توافق‌شده است.' if fa else 'Before starting, we agree on scope, responsibilities, timing, fees and reporting. We do not guarantee grades, admissions or scholarships; we take responsibility for coordinating and reviewing the services we agree to deliver.'}</p></div><div class="illustration-card"><span>ILLUSTRATIVE ROADMAP / NOT A REAL CLIENT</span><div class="roadmap-row"><i></i><strong>01 · {'شناخت' if fa else 'Discover'}</strong></div><div class="roadmap-row"><i></i><strong>02 · {'اولویت‌بندی' if fa else 'Prioritise'}</strong></div><div class="roadmap-row"><i></i><strong>03 · {'هماهنگی' if fa else 'Coordinate'}</strong></div><div class="roadmap-row"><i></i><strong>04 · {'سنجش' if fa else 'Review'}</strong></div></div></div></section>'''
 return p+closing(lang)

def pathways_page(lang):
 fa=lang=='fa'
 p=interior_hero(lang,'YOUR PATHWAY','مسیر شما','از امروز تا مرحله بعد؛ با مسیر مخصوص خودتان.' if fa else 'Your stage. Your goals. Your own way forward.','شاید به پایه‌ریزی عادت‌های یادگیری نیاز دارید یا برنامه دقیق آزمون و دانشگاه؛ نقطه شروع هر فرد فرق می‌کند.' if fa else 'Whether the immediate need is learning confidence or an ambitious university plan, the starting point is always the student.')
 cards=([('01','۸ تا ۱۲ سال','سال‌های پایه','کشف علایق، تقویت ریاضی، علوم، زبان و مهارت‌های یادگیری؛ همراه با توجه به رشد متعادل و علایق کودک.'),('02','۱۳ تا ۱۸ سال','دبیرستان و مسیر دانشگاه','آموزش و آمادگی آزمون، IGCSE و A Level، رشد علمی و فردی، پروژه‌ها، رقابت‌ها و انتخاب دانشگاه.'),('03','۱۸ سال به بالا','دانشگاه و تحصیلات تکمیلی','شناخت فرصت‌های متناسب، برنامه‌ریزی آموزشی یا پژوهشی و آماده‌سازی درخواست‌های دانشگاهی.')]
 if fa else [('01','AGES 8–12','Strong foundations','Personalised learning, curiosity, core subjects, study habits and age-appropriate talent discovery.'),('02','AGES 13–18','School to university','Curricula and exams, academic mentoring, meaningful projects, competitions and university strategy.'),('03','18+','University & beyond','Academic direction, research preparation, opportunities and tailored undergraduate or postgraduate applications.')])
 p+='<section class="section"><div class="container"><div class="pathway-list">'+''.join(f'<article class="pathway-detail"><span class="path-tag">{age}</span><span class="path-number">{n}</span><div><h2>{t}</h2><p>{d}</p>{cta(lang,"text-cta dark")}</div></article>' for n,age,t,d in cards)+'</div></div></section>'
 return p+closing(lang)

def about_page(lang):
 fa=lang=='fa'
 p=interior_hero(lang,'ABOUT VELLUM HOUSE','درباره ولوم هاوس','آینده‌های درخشان، با مسیرهای یکسان ساخته نمی‌شوند.' if fa else 'Exceptional futures are never one-size-fits-all.','ما با دانش‌آموزان و خانواده‌ها همراه می‌شویم تا استعدادها را به رشد قابل پیگیری تبدیل کنیم؛ با آموزش تخصصی، منتورینگ راهبردی، پرورش توانمندی و برنامه‌ریزی برای فرصت‌های آموزشی.' if fa else 'We partner with students and families to turn potential into progress through expert teaching, strategic mentorship, talent development and thoughtful university planning.')
 p+=f'''<section class="section about-manifesto"><div class="container split-layout"><div>{eyebrows('WHY WE EXIST','چرا ولوم هاوس؟',lang)}<h2>{'آموزش باید از خودِ فرد شروع شود.' if fa else 'Education should start with the individual.'}</h2><p class="section-lead">{'هر دانش‌آموز مجموعه‌ای متفاوت از استعدادها، علایق، نیازها و فرصت‌هاست. وظیفه ما این است که این تصویر را یکپارچه ببینیم و به تصمیم‌ها و اقدام‌های هماهنگ تبدیل کنیم.' if fa else 'Every student brings a distinct mix of strengths, interests, needs and opportunities. Our role is to see the whole picture—and turn it into deliberate, connected action.'}</p></div>{media('TEAM / EDITORIAL PHOTO','about-photo')}</div></section>'''
 bios=([('ریحانه وجودی','بنیان‌گذار · راهبری علمی و آموزشی','کارشناسی ارشد گرانش و کیهان‌شناسی؛ مدرس و پژوهشگر فیزیک با سابقه آموزش، پژوهش و هدایت علمی.'),('کسری پهلوانی','هم‌بنیان‌گذار','کارشناسی ارشد مهندسی مخابرات. جزئیات نقش اجرایی و سوابق حرفه‌ای در نسخه نهایی تکمیل می‌شود.')]
 if fa else [('Reyhaneh Vojoudi','Founder · Academic & educational direction','MSc in Gravity and Cosmology; physics educator and researcher with experience in teaching, research and academic guidance.'),('Kasra Pahlavani','Co-founder','MSc in Telecommunication Engineering. Detailed professional biography and responsibilities will be added to the final edition.')])
 p+=f'''<section class="section founders-section"><div class="container">{eyebrows('MEET THE FOUNDERS','آشنایی با بنیان‌گذاران',lang)}<h2>{'آشنایی با کسانی که مسیر را هدایت می‌کنند.' if fa else 'The people behind the direction.'}</h2><div class="founder-cards">'''+''.join(f'<article class="founder-card">{media("FOUNDER PORTRAIT" if i==0 else "CO-FOUNDER PORTRAIT")}<h3>{nm}</h3><span class="role">{role}</span><p>{bio}</p></article>' for i,(nm,role,bio) in enumerate(bios))+f'</div></div></section><section class="section expert-section"><div class="container split-layout"><div>{eyebrows("OUR SPECIALIST NETWORK","تیم متخصصان",lang)}<h2>{"متخصص مناسب برای نیاز مناسب." if fa else "The right expertise, when it matters."}</h2><p>{"مدرسان، منتورها و مشاوران متناسب با هدف‌های هر دانش‌آموز انتخاب و هماهنگ می‌شوند. معرفی اعضای تیم پس از تکمیل مشخصات و دریافت تأیید آن‌ها منتشر خواهد شد." if fa else "Educators, mentors and advisers are selected around each student’s needs. Detailed profiles will be published after verification and consent."}</p></div><div class="team-slots">{media("EXPERT / PORTRAIT")}{media("EXPERT / PORTRAIT")}{media("EXPERT / PORTRAIT")}</div></div></section>'''
 return p+closing(lang)

def interior_hero(lang,ey_en,ey_fa,title,lead):
 return f'<section class="interior-hero"><div class="container">{eyebrows(ey_en,ey_fa,lang)}<h1>{title}</h1><p>{lead}</p></div><div class="hero-watermark" aria-hidden="true">VH.</div></section>'

def contact_page(lang):
 fa=lang=='fa'
 p=interior_hero(lang,'THE FIRST CONVERSATION','اولین گفت‌وگو','با شناخت شروع کنیم؛ بدون هیچ تعهدی.' if fa else 'A thoughtful first conversation. On us.','فرم کوتاه را تکمیل کنید؛ بعد از ثبت موفق درخواست، مستقیم به صفحه انتخاب زمان جلسه آنلاین رایگان ۳۰ دقیقه‌ای منتقل می‌شوید.' if fa else 'Share a little about your needs. Once your enquiry is saved, you’ll go straight to the calendar to choose a free 30-minute online meeting.')
 notes=([('چه چیزی می‌فهمیم؟','شرایط فعلی، مهم‌ترین پرسش‌ها، هدف‌ها و اینکه آیا همکاری با ولوم هاوس برای شما مناسب است.'),('چه کسانی حضور داشته باشند؟','برای دانش‌آموزان زیر ۱۸ سال، حضور دست‌کم یکی از والدین یا سرپرست ضروری است. حضور دانش‌آموز نیز توصیه می‌شود.'),('بعد از جلسه چه می‌شود؟','در صورت تناسب و تمایل دو طرف، ارزیابی تخصصی یا طرح خدمات و هزینه به‌صورت جداگانه پیشنهاد می‌شود.')]
 if fa else [('What will we discuss?','Your starting point, your goals, the main challenges and whether Vellum House is a suitable match.'),('Who should attend?','For students under 18, at least one parent or guardian must attend. Student participation is encouraged.'),('What happens afterwards?','If there is a mutual fit, we may propose a separate assessment or a tailored service scope and fee.')])
 opts=([('','حوزه موردنظر را انتخاب کنید'),('full','مدیریت کامل مسیر تحصیلی'),('classes','کلاس و آمادگی آزمون'),('mentoring','منتورینگ و سنجش پیشرفت'),('talent','استعداد، پروژه و مسابقات'),('university','پذیرش دانشگاه'),('other','هنوز مطمئن نیستم')]
 if fa else [('','Choose an area of interest'),('full','Complete academic management'),('classes','Classes & exam preparation'),('mentoring','Mentoring & progress tracking'),('talent','Talent, projects & competitions'),('university','University admissions'),('other','Not sure yet')])
 options=''.join(f'<option value="{v}"'+(' disabled selected' if not v else '')+f'>{lab}</option>' for v,lab in opts)
 p+=f'''<section class="section enquiry-section"><div class="container enquiry-grid"><div class="enquiry-context">{eyebrows('WHAT TO EXPECT','در جلسه آشنایی چه می‌گذرد؟',lang)}<h2>{'۳۰ دقیقه برای یک نقطه شروع روشن‌تر.' if fa else '30 minutes to find a clearer starting point.'}</h2><div class="expect-list">'''+''.join(f'<div><h3>{t}</h3><p>{d}</p></div>' for t,d in notes)+f'''</div><p class="no-promise">{'جلسه اولیه رایگان است. تکمیل فرم یا شرکت در جلسه، به معنای آغاز همکاری و پرداخت هزینه نیست.' if fa else 'The initial meeting is free. Enquiring or attending does not create a paid commitment.'}</p></div><div class="enquiry-panel"><div class="form-heading"><span>01 / {'درخواست آشنایی' if fa else 'ENQUIRY'}</span><h2>{'اول کمی از خودتان بگویید.' if fa else 'Tell us a little about you.'}</h2><p>{'فیلدهای ستاره‌دار ضروری هستند. برای افراد زیر ۱۸ سال، فرم را والد یا سرپرست تکمیل کند.' if fa else 'Only starred fields are required. A parent or guardian should enquire for students under 18.'}</p></div><form id="enquiry-form" method="post" action="" novalidate><div class="form-row"><div class="field"><label for="fullName">{'نام و نام خانوادگی والد یا متقاضی' if fa else 'Parent / applicant name'} <b>*</b></label><input id="fullName" name="fullName" autocomplete="name" maxlength="120" required></div><div class="field"><label for="email">{'ایمیل' if fa else 'Email address'} <b>*</b></label><input id="email" name="email" type="email" autocomplete="email" maxlength="200" dir="ltr" required></div></div><div class="form-row"><div class="field"><label for="phone">{'شماره تماس (اختیاری)' if fa else 'Phone (optional)'}</label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40" dir="ltr" placeholder="+98 ..."></div><div class="field"><label for="grade">{'پایه یا مقطع تحصیلی (اختیاری)' if fa else 'Grade / study level (optional)'}</label><input id="grade" name="grade" maxlength="100" autocomplete="off" placeholder="{'مثلاً پایه دهم' if fa else 'e.g. Grade 10'}"></div></div><div class="field"><label for="serviceInterest">{'بیشتر در چه زمینه‌ای همراهی می‌خواهید؟' if fa else 'What are you looking for?'} <b>*</b></label><select id="serviceInterest" name="serviceInterest" required>{options}</select></div><div class="field"><label for="message">{'دغدغه یا هدف شما (اختیاری)' if fa else 'Your goal or question (optional)'}</label><textarea id="message" name="message" rows="3" maxlength="2000" placeholder="{'در یک یا دو جمله کافی است.' if fa else 'A sentence or two is enough.'}"></textarea></div><div class="honeypot" aria-hidden="true"><label for="website">Do not fill</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><label class="consent"><input type="checkbox" name="consent" value="yes" required><span>{'با استفاده از اطلاعاتم برای پاسخ به این درخواست موافقم و ' if fa else 'I agree to be contacted about this enquiry and have read the '}{a('privacy','اطلاعیه حریم خصوصی' if fa else 'privacy notice',lang,'inline-link')}{' را خوانده‌ام.' if fa else '.'}</span></label><button class="btn btn-gold form-submit" type="submit">{'ثبت درخواست و انتخاب زمان جلسه' if fa else 'Submit enquiry & choose a time'} <span aria-hidden="true">↗</span></button><p class="form-disclaimer">{'بعد از ثبت موفق، صفحه رزرو باز می‌شود؛ نهایی شدن جلسه منوط به انتخاب زمان در تقویم است.' if fa else 'After confirmed submission, the booking page opens. Your meeting is not reserved until you choose a time.'}</p><div id="form-status" tabindex="-1" role="status" aria-live="polite"></div><div id="booking-fallback" class="booking-fallback" hidden><p>{'درخواست شما ثبت شد. اگر تقویم باز نشد، از دکمه زیر استفاده کنید:' if fa else 'Your enquiry was saved. If the calendar did not open, use this link:'}</p><a id="booking-link" href="https://cal.com/vhouse/30min" class="btn btn-outline" rel="noopener noreferrer">{'انتخاب زمان جلسه' if fa else 'Continue to free booking'}</a></div><noscript><p class="form-error">{'برای حفظ امنیت اطلاعات، ارسال این فرم نیازمند فعال بودن جاوااسکریپت است. لطفاً به vellumhouse.edu@gmail.com ایمیل بزنید.' if fa else 'To protect your information, this form requires JavaScript. Please email vellumhouse.edu@gmail.com.'}</p></noscript></form></div></div></section>'''
 faqs=([('آیا جلسه اول واقعاً رایگان است؟','بله. جلسه آشنایی آنلاین ۳۰ دقیقه‌ای رایگان است. ارزیابی‌های تخصصی و خدمات پس از آن، در صورت نیاز، هزینه جداگانه دارند.'),('آیا می‌توانم فقط کلاس یا مشاوره بگیرم؟','بله. همکاری می‌تواند جامع یا محدود به یک خدمت مشخص باشد.'),('هزینه خدمات چقدر است؟','پس از شناخت نیاز و مشخص شدن محدوده خدمات، پیشنهاد و هزینه اختصاصی اعلام می‌شود.'),('آیا پذیرش در دانشگاه تضمینی است؟','خیر. پذیرش و بورسیه به تصمیم دانشگاه‌ها و شرایط هر متقاضی وابسته است؛ ما برنامه‌ریزی و پشتیبانی توافق‌شده را ارائه می‌کنیم.')]
 if fa else [('Is the first call really free?','Yes. The first 30-minute online conversation is free. Any assessment or ongoing service is proposed and priced separately.'),('Can we book only classes or mentoring?','Yes. We can manage the complete journey or provide individual services.'),('How much do services cost?','Fees are personalised after we understand your needs and agree the scope.'),('Can you guarantee university admission?','No. Admissions and scholarship decisions belong to universities; we provide agreed planning and support, not guarantees.')])
 p+=f'<section class="section faqs-section"><div class="container faq-wrap">{eyebrows("GOOD TO KNOW","پرسش‌های رایج",lang)}<h2>{"پاسخ چند پرسش مهم" if fa else "A few helpful answers"}</h2>'+''.join(f'<details><summary>{t}<span aria-hidden="true">+</span></summary><p>{d}</p></details>' for t,d in faqs)+'</div></section>'
 return p

def journal_page(lang):
 fa=lang=='fa'
 p=interior_hero(lang,'IDEAS & RESOURCES','راهنماها و منابع','پرسش‌های خوب، نقطه شروع تصمیم‌های بهترند.' if fa else 'Good questions lead to better decisions.','این بخش به‌تدریج با مطالب علمی، راهنماها و تجربه‌های قابل استناد کامل می‌شود.' if fa else 'Our resources will grow with practical, responsibly sourced guidance for students and families.')
 p+=f'''<section class="section"><div class="container"><div class="resource-grid"><article><span>01 / {'پیش از جلسه' if fa else 'BEFORE YOUR CALL'}</span><h2>{'سه نکته برای گفت‌وگوی اول' if fa else 'Prepare for your first conversation'}</h2><p>{'چالش اصلی، نزدیک‌ترین مهلت و تغییری که دوست دارید در مسیر تحصیلی اتفاق بیفتد را مرور کنید.' if fa else 'Think about your main challenge, nearest deadline and what meaningful progress would look like.'}</p>{cta(lang,'text-cta dark')}</article><article><span>02 / {'آشنایی با خدمات' if fa else 'GET TO KNOW US'}</span><h2>{'خدمات و روش کار ما' if fa else 'Our services and approach'}</h2><p>{'برای شناخت تفاوت برنامه جامع با خدمات مستقل، از صفحه خدمات بازدید کنید.' if fa else 'See how complete academic management differs from individual services.'}</p>{a('services','مشاهده خدمات' if fa else 'Explore services',lang,'text-cta dark')}</article></div></div></section>'''
 return p+closing(lang)

def privacy_page(lang):
 fa=lang=='fa'
 p=interior_hero(lang,'YOUR PRIVACY','حریم خصوصی','اطلاعات شما، با احترام و احتیاط.' if fa else 'Your information, treated with care.','می‌خواهیم دقیقاً بدانید هنگام ارسال فرم آشنایی چه اطلاعاتی دریافت می‌کنیم و چرا.' if fa else 'An overview of what happens when you submit an enquiry and how you can exercise your choices.')
 data=([('چه اطلاعاتی دریافت می‌کنیم؟','نام تماس‌گیرنده، ایمیل، و در صورت ارائه شماره تماس، مقطع، موضوع علاقه‌مندی و توضیحات؛ به‌علاوه زمان و شناسه ثبت درخواست. لطفاً اطلاعات پزشکی، هویتی حساس یا اسناد محرمانه را در فرم وارد نکنید.'),('اطلاعات کجا ذخیره می‌شود؟','در یک Google Sheet خصوصی متعلق به مجموعه ذخیره می‌شود و به vellumhouse.edu@gmail.com اعلان ایمیلی فرستاده می‌شود. تأیید دریافت نیز به ایمیل شما ارسال خواهد شد. خدمات گوگل و Cal.com طبق سیاست‌های خودشان داده‌های مربوط را پردازش می‌کنند.'),('چه استفاده‌ای از اطلاعات می‌کنیم؟','فقط برای رسیدگی به درخواست، فراهم کردن امکان رزرو جلسه، پاسخ‌گویی و بررسی امکان ارائه خدمات. ارسال فرم به معنای عضویت در خبرنامه تبلیغاتی نیست.'),('درخواست دسترسی، اصلاح و حذف','برای درخواست دسترسی، اصلاح یا حذف اطلاعات فرم به vellumhouse.edu@gmail.com ایمیل بزنید. اطلاعات تا زمانی نگهداری می‌شود که برای رسیدگی به درخواست یا همکاری توافق‌شده ضرورت داشته باشد؛ می‌توانید درخواست بررسی یا حذف آن را ثبت کنید.'),('کودکان و نوجوانان','برای دانش‌آموزان زیر ۱۸ سال، فرم را یکی از والدین یا سرپرست تکمیل کند. هدف ما دریافت حداقل اطلاعات لازم در گام نخست است.')]
 if fa else [('What we collect','The contact person’s name and email; optionally phone, study level, area of interest and message; plus submission time and a request ID. Do not send sensitive identification, health or confidential documents using this form.'),('Where it goes','Enquiries are stored in a private Google Sheet and a notification is emailed to vellumhouse.edu@gmail.com. You receive an acknowledgement. Google and Cal.com process relevant data under their respective policies.'),('How we use it','To respond to your enquiry, enable booking, assess fit and discuss appropriate services. Submitting the form does not opt you into marketing.'),('Your choices','Email vellumhouse.edu@gmail.com to request access, correction or deletion. We retain information only as needed to respond to enquiries or manage agreed services, subject to applicable obligations, and you may request deletion.'),('Minors','A parent or guardian should submit an enquiry for a student under 18. We request only what is useful at first contact.')])
 p+='<section class="section"><div class="container policy-list">'+''.join(f'<article><h2>{t}</h2><p>{d}</p></article>' for t,d in data)+'</div></section>'
 return p

def terms_page(lang):
 fa=lang=='fa'
 p=interior_hero(lang,'WORKING TOGETHER','شرایط همکاری','چارچوب روشن، همکاری بهتر.' if fa else 'Clear expectations make better partnerships.','این توضیحات عمومی است؛ شرایط مالی، زمان‌بندی و محدوده خدمات هر پرونده پیش از شروع کار به‌صورت کتبی توافق می‌شود.' if fa else 'These are general service expectations. Individual scope, schedules, fees, payment and cancellation terms must be agreed in writing before paid work begins.')
 data=([('جلسه اولیه رایگان','جلسه آشنایی آنلاین ۳۰ دقیقه‌ای رایگان است. تکمیل فرم به‌تنهایی به معنای رزرو زمان یا آغاز همکاری نیست؛ رزرو از طریق تقویم انجام می‌شود.'),('خدمات اختصاصی','محدوده خدمات و کارشناسان متناسب با نیاز فرد مشخص می‌شوند. ممکن است خدمات به‌صورت یک برنامه جامع یا خدمات مستقل ارائه شوند.'),('هزینه، لغو و استرداد','تعرفه، شیوه پرداخت، سیاست تغییر یا لغو کلاس و شرایط استرداد باید پیش از قرارداد مالی به‌صورت شفاف در توافق اختصاصی درج شوند.'),('نتایج و مسئولیت‌ها','هیچ نمره، پذیرش یا بورسیه‌ای تضمین نمی‌شود. مسئولیت ولوم هاوس در قبال خدمات و پیگیری‌ها محدود به موارد توافق‌شده است.'),('ارتباط و حفاظت از داده‌ها','برای دانش‌آموزان زیر ۱۸ سال، حضور و رضایت والد یا سرپرست در فرایند ضروری است. برای درخواست‌های مربوط به داده‌ها از ایمیل رسمی مجموعه استفاده کنید.')]
 if fa else [('Free first meeting','The 30-minute introduction is free. Submitting an enquiry does not reserve a calendar time or create a paid engagement.'),('Personalised services','We agree the service scope and specialists based on individual needs. Full management and single-service arrangements are both available.'),('Fees, cancellation and refunds','Pricing, payment, cancellation, rescheduling and refund arrangements must be clearly agreed in writing before paid services start.'),('Outcomes and accountability','We do not guarantee grades, admission or scholarships. Our obligations are limited to the agreed coordination and support deliverables.'),('Communication and safeguards','Parents or guardians participate in the process for students under 18. Questions regarding personal information can be sent to the Vellum House email.')])
 p+='<section class="section"><div class="container policy-list">'+''.join(f'<article><h2>{t}</h2><p>{d}</p></article>' for t,d in data)+'</div></section>'
 return p

CONTENT={'home':home,'services':service_page,'approach':approach_page,'pathways':pathways_page,'about':about_page,'contact':contact_page,'journal':journal_page,'privacy':privacy_page,'terms':terms_page}
for lang in LANGS:
 for key,render in CONTENT.items():
  (R/fn(key,lang)).write_text(wrap(key,lang,render(lang)),encoding='utf-8')
(R/'fa.html').write_text((R/'index.html').read_text(encoding='utf-8'),encoding='utf-8')
(R/'404.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found | Vellum House</title><link rel="stylesheet" href="assets/style.css"><main class="error-page"><h1>Page not found.</h1><p>صفحه مورد نظر پیدا نشد.</p><p><a class="btn btn-gold" href="index.html">فارسی</a> <a class="btn btn-gold" href="en.html">English</a></p></main></html>',encoding='utf-8')
urls=list(dict.fromkeys([BASE if k=='home' and l=='fa' else BASE+fn(k,l) for k in CONTENT for l in LANGS]))
(R/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('  <url><loc>'+e(u)+'</loc></url>\n' for u in urls)+'</urlset>',encoding='utf-8')
(R/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://vhouse.ir/sitemap.xml\n',encoding='utf-8')
(R/'CNAME').write_text('vhouse.ir\n',encoding='utf-8')
print(f'Generated {len(CONTENT)*2+2} HTML pages + sitemap, robots.txt and CNAME')
